import{_ as a,o as e,a as r,b as o}from"./app.C41L12d5.js";const i="/ascendc.github.io/assets/ub_gm_bw.BxcEzh4M.png",s="/ascendc.github.io/assets/gm_ub_bw.D238Ga1G.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子性能优化","link":"/guide/operator_practice/simd_operator_optimization/simd_operator_optimization"},{"text":"内存访问","link":"/guide/operator_practice/simd_operator_optimization/memory_access/memory_access"},{"text":"尽量一次搬运较大的数据块","link":"/guide/operator_practice/simd_operator_optimization/memory_access/transfer_larger_data_blocks"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_optimization/memory_access/transfer_larger_data_blocks.md","filePath":"guide/operator_practice/simd_operator_optimization/memory_access/transfer_larger_data_blocks.md","lastUpdated":1787050286000}'),_={name:"guide/operator_practice/simd_operator_optimization/memory_access/transfer_larger_data_blocks.md"};function c(p,t,n,d,l,m){return e(),r("div",null,[...t[0]||(t[0]=[o('<div><article class="markdown-body"><h1>尽量一次搬运较大的数据块<span id="ZH-CN_TOPIC_0000001893771813"></span></h1><p>【优先级】高</p><p>【描述】搬运不同大小的数据块时，对带宽的利用率（有效带宽/理论带宽）不一样。根据实测经验，单次搬运数据长度16KB以上时，通常能较好地发挥出带宽的最佳性能。因此对于单次搬运，应考虑尽可能的搬运较大的数据块。下图展示了某款AI处理器上实测的不同搬运数据量下带宽的变化图。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>测试数据与处理器型号相关，且实际测试时可能会存在略微抖动，具体带宽数值并不一定和下文的测试数据严格一致。</p></div><p><strong>图1</strong> UB-&gt;GM方向不同单次搬运数据量下实际占用带宽的变化<span id="fig925755124312"></span><br><img src="'+i+'" alt title="UB--GM方向不同单次搬运数据量下实际占用带宽的变化"></p><p><strong>图2</strong> GM-&gt;UB方向不同单次搬运数据量下实际占用带宽的变化<span id="fig859712315453"></span><br><img src="'+s+'" alt title="GM--UB方向不同单次搬运数据量下实际占用带宽的变化"></p></article></div>',1)])])}const h=a(_,[["render",c]]);export{u as __pageData,h as default};
